Q: std::forward_list&lt;T&gt;::insert_after implementation A: <p>I decided to do it this way<br />
Replace</p>
<pre><code>using base_node_t = std::conditional_t&lt;isConst, const __fl_detail::base_node, __fl_detail::base_node&gt;; 
using node_t = std::conditional_t&lt;isConst, const __fl_detail::node&lt;T&gt;, __fl_detail::node&lt;T&gt;&gt;;
</code></pre>
<pre><code>using base_node_t = __fl_detail::base_node;
using node_t = std::conditional_t&lt;isConst, __fl_detail::node&lt;const T&gt;, __fl_detail::node&lt;T&gt;&gt;;
</code></pre>
<p>And implement insert_after like this</p>
<pre><code>    iterator insert_after(const_iterator pos, const_reference value) {
        assert(pos._ptr != nullptr);

        node_t* new_node = node_allocator_traits::allocate(alloc(), 1);

        try {
            node_allocator_traits::construct(alloc(), new_node, value);
        } catch (...) {
            node_allocator_traits::deallocate(alloc(), new_node, 1);
        }

        new_node-&gt;_next = pos._ptr-&gt;_next;
        pos._ptr-&gt;_next =  new_node;

        return iterator(new_node);
    }
</code></pre>
